+using Microsoft.AspNetCore.Routing;
+using Microsoft.Extensions.Options;
+using Xunit;
+
+namespace InvoiceApp.Tests;
+
+public class RoleMigrationTests
+{
+    [Fact]
+    public void SignIn_ReturnsConfiguredRoleAndStoresItInSession()
+    {
+        var options = LoadDemoUsers();
+        Assert.Collection(
+            options.Users,
+            manager =>
+            {
+                Assert.Equal("demo.approver", manager.Username);
+                Assert.Equal("ChangeMe123!", manager.Password);
+                Assert.Equal("Manager", manager.Role);
+            },
+            director =>
+            {
+                Assert.Equal("demo.admin", director.Username);
+                Assert.Equal("ChangeMe123!", director.Password);
+                Assert.Equal("Director", director.Role);
+            });
+
+        var sessions = new SessionStore();
+        var controller = new AuthController(Options.Create(options), sessions);
+
+        foreach (var user in options.Users)
+        {
+            var result = controller.Login(new AuthController.LoginRequest(user.Username, user.Password));
+            var response = Assert.IsType<AuthController.LoginResponse>(Assert.IsType<OkObjectResult>(result.Result).Value);
+
+            Assert.Equal(user.Role, response.Role);
+            Assert.Equal(user.Username, response.Username);
+            Assert.Equal(new UserSession(user.Username, user.Role), sessions.Get(response.Token));
+        }
+    }
+
+    [Theory]
+    [InlineData("Manager", true)]
+    [InlineData("Director", true)]
+    [InlineData("Approver", false)]
+    [InlineData("Admin", false)]
+    public void ApprovalsController_RequiresMigratedRoles(string role, bool isAllowed)
+    {
+        var attribute = typeof(ApprovalsController).GetCustomAttributes(typeof(RequireRoleAttribute), true)
+            .Cast<RequireRoleAttribute>()
+            .Single();
+
+        AssertAuthorization(attribute, role, isAllowed);
+    }
+
+    [Theory]
+    [InlineData("Director", true)]
+    [InlineData("Manager", false)]
+    [InlineData("Admin", false)]
+    public void InvoiceDeletion_RequiresDirectorRole(string role, bool isAllowed)
+    {
+        var deleteMethod = typeof(InvoicesController).GetMethod(nameof(InvoicesController.Delete));
+        Assert.NotNull(deleteMethod);
+        var attribute = deleteMethod.GetCustomAttributes(typeof(RequireRoleAttribute), true)
+            .Cast<RequireRoleAttribute>()
+            .Single();
+
+        AssertAuthorization(attribute, role, isAllowed);
+    }
+
+    private static void AssertAuthorization(RequireRoleAttribute attribute, string role, bool isAllowed)
+    {
+        var httpContext = new DefaultHttpContext();
+        httpContext.Items[HttpContextExtensions.SessionKey] = new UserSession("test.user", role);
+        var actionContext = new ActionContext(httpContext, new RouteData(), new ActionDescriptor());
+        var context = new ActionExecutingContext(
+            actionContext,
+            new List<IFilterMetadata>(),
+            new Dictionary<string, object?>(),
+            new object());
+
+        attribute.OnActionExecuting(context);
+
+        if (isAllowed)
+        {
+            Assert.Null(context.Result);
+        }
+        else
+        {
+            Assert.Equal(StatusCodes.Status403Forbidden, Assert.IsType<StatusCodeResult>(context.Result).StatusCode);
+        }
+    }
+
+    private static DemoUsersOptions LoadDemoUsers()
+    {
+        var directory = new DirectoryInfo(AppContext.BaseDirectory);
+        while (directory is not null)
+        {
+            var path = Path.Combine(directory.FullName, "backend", "src", "InvoiceApp.Api", "appsettings.json");
+            if (File.Exists(path))
+            {
+                return JsonSerializer.Deserialize<DemoUsersOptions>(File.ReadAllText(path))
+                    ?? throw new InvalidDataException("Demo user configuration could not be loaded.");
+            }
+
+            directory = directory.Parent;
+        }
+
+        throw new FileNotFoundException("Could not locate the API appsettings.json file.");
+    }
+}
