input.command:
$ErrorActionPreference = 'Stop'
$logPath = Join-Path $env:TEMP ('subagent-hook-' + [guid]::NewGuid().ToString('N') + '.jsonl')
$env:AI_INTERACTION_LOG_PATH = $logPath
function Send-Hook($eventObject) {
  $json = $eventObject | ConvertTo-Json -Depth 10 -Compress
  $output = $json | node .github/hooks/log-interaction.cjs
  if ($LASTEXITCODE -ne 0) { throw "Hook logger exited with $LASTEXITCODE" }
  if (($output -join '').Trim() -ne '{}') { throw "Unexpected hook output: $output" }
}
try {
  node --check .github/hooks/log-interaction.cjs
  if ($LASTEXITCODE -ne 0) { throw 'JavaScript syntax check failed' }
